def transform(grid):
    h, w = len(grid), len(grid[0])
    # The colored seed marks a stencil. Find its cells and stamp the color
    # wherever that stencil overlays only zero cells.
    colors = {v for row in grid for v in row if v not in (0, 5, 9)}
    if not colors:
        colors = {v for row in grid for v in row if v not in (0, 9)}
    color = next(iter(colors))
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    out = [row[:] for row in grid]
    minr, minc = min(r for r, c in pts), min(c for r, c in pts)
    shape = [(r-minr, c-minc) for r, c in pts]
    sh, sw = max(r for r, c in shape)+1, max(c for r, c in shape)+1
    for r in range(h-sh+1):
        for c in range(w-sw+1):
            if all(grid[r+dr][c+dc] == 0 for dr, dc in shape):
                for dr, dc in shape:
                    out[r+dr][c+dc] = color
    return out

