def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    crosses = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                y, x = stack.pop()
                component.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if 0 <= p[0] < h and 0 <= p[1] < w and grid[p[0]][p[1]] == 2 and p not in seen:
                        seen.add(p)
                        stack.append(p)
            if len(component) == 5:
                rs = [p[0] for p in component]
                cs = [p[1] for p in component]
                cr, cc = (min(rs) + max(rs)) // 2, (min(cs) + max(cs)) // 2
                expected = {(cr, cc), (cr - 1, cc), (cr + 1, cc), (cr, cc - 1), (cr, cc + 1)}
                if set(component) == expected:
                    crosses.append((cr, cc))
    by_row = {}
    by_col = {}
    for r, c in crosses:
        by_row.setdefault(r, []).append(c)
        by_col.setdefault(c, []).append(r)
    for r, cs in by_row.items():
        cs.sort()
        for a, b in zip(cs, cs[1:]):
            for c in range(a + 2, b - 1):
                if out[r][c] == 0:
                    out[r][c] = 1
    for c, rs in by_col.items():
        rs.sort()
        for a, b in zip(rs, rs[1:]):
            for r in range(a + 2, b - 1):
                if out[r][c] == 0:
                    out[r][c] = 1
    return out

