def _segments(values, color):
    segs = []
    i = 0
    while i < len(values):
        if values[i] != color:
            i += 1
            continue
        start = i
        while i < len(values) and values[i] == color:
            i += 1
        segs.append((start, i))
    return segs


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    counts = {}
    for row in out:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    candidates = []
    # Horizontal bars on the top and bottom edges.
    for color in set(out[0]) & set(out[-1]):
        for top in _segments(out[0], color):
            for bottom in _segments(out[-1], color):
                if top[1] - top[0] == bottom[1] - bottom[0] and top[1] - top[0] >= 2:
                    candidates.append(("h", color, top, bottom))
    # Vertical bars on the left and right edges.
    left_edge = [out[r][0] for r in range(h)]
    right_edge = [out[r][-1] for r in range(h)]
    for color in set(left_edge) & set(right_edge):
        for left in _segments(left_edge, color):
            for right in _segments(right_edge, color):
                if left[1] - left[0] == right[1] - right[0] and right[1] - right[0] >= 2:
                    candidates.append(("v", color, left, right))
    if not candidates:
        return out

    # The paired equal-length segments are the border encoding.
    axis, bar_color, first, second = max(candidates, key=lambda x: x[2][1] - x[2][0])
    markers = [(r, c, out[r][c]) for r in range(1, h - 1) for c in range(1, w - 1)
               if out[r][c] != background and out[r][c] != bar_color]

    for r, c, ink in markers:
        if axis == "h":
            if first[0] <= c < first[1]:
                k = c - first[0]
                # Marker aligns with the first (top) bar: ray toward top.
                for rr in range(1, r):
                    out[rr][c] = ink
                opposite_col = second[0] + k
            elif second[0] <= c < second[1]:
                k = c - second[0]
                # Marker aligns with the second (bottom) bar: ray toward bottom.
                for rr in range(r + 1, h - 1):
                    out[rr][c] = ink
                opposite_col = first[0] + k
            else:
                continue
            for rr in range(1, h - 1):
                out[rr][opposite_col] = ink
        else:
            if first[0] <= r < first[1]:
                k = r - first[0]
                # Marker aligns with the first (left) bar: ray toward left.
                for cc in range(1, c):
                    out[r][cc] = ink
                opposite_row = second[0] + k
            elif second[0] <= r < second[1]:
                k = r - second[0]
                # Marker aligns with the second (right) bar: ray toward right.
                for cc in range(c + 1, w - 1):
                    out[r][cc] = ink
                opposite_row = first[0] + k
            else:
                continue
            for cc in range(1, w - 1):
                out[opposite_row][cc] = ink
        out[r][c] = 4
    return out

