def transform(grid):
    """Extend the diagonal clue coloring across the grid."""
    h, w = len(grid), len(grid[0])
    # The encoded traces run along constant column-minus-row diagonals.
    clues = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                clues.setdefault(c - r, []).append((r, color))
    # If multiple traces cross the same diagonal offset, the lower/right-most
    # trace determines that offset's color. Extend nearest known offset.
    colors = {k: sorted(vals)[-1][1] for k, vals in clues.items()}
    if not colors:
        raise ValueError("no diagonal clues")
    keys = sorted(colors)
    out = []
    for r in range(h):
        row_out = []
        for c in range(w):
            k = c - r
            if k in colors:
                row_out.append(colors[k])
            else:
                nearest = min(keys, key=lambda x: (abs(x-k), x))
                row_out.append(colors[nearest])
        out.append(row_out)
    return out


