def transform(grid):
    """Tile the color sequence encoded on homogeneous diagonal strokes."""
    h, w = len(grid), len(grid[0])
    options = []
    for kind in ("sum", "diff"):
        lines = {}
        for r, row in enumerate(grid):
            for c, color in enumerate(row):
                if color:
                    k = r + c if kind == "sum" else c - r
                    lines.setdefault(k, []).append(color)
        clean = {k: vals[0] for k, vals in lines.items()
                 if len(set(vals)) == 1}
        score = sum(len(lines[k]) for k in clean)
        options.append((score, kind, clean))
    _, kind, clues = max(options, key=lambda x: x[0])
    if not clues:
        raise ValueError("no homogeneous diagonal clues")
    period = None
    residues = None
    for p in range(2, len(clues) + 1):
        mapping = {}
        for k, color in clues.items():
            q = k % p
            if q in mapping and mapping[q] != color:
                break
            mapping[q] = color
        else:
            if len(mapping) == p:
                period, residues = p, mapping
                break
    if period is None:
        # Sparse encodings may leave a phase unseen; keep the shortest
        # conflict-free cycle and extend each missing phase from its neighbor.
        for p in range(2, len(clues) + 1):
            mapping = {}
            for k, color in clues.items():
                q = k % p
                if q in mapping and mapping[q] != color:
                    break
                mapping[q] = color
            else:
                period, residues = p, mapping
                break
    if period is None:
        raise ValueError("diagonal clues conflict")
    known = list(residues)
    for q in range(period):
        if q not in residues:
            near = min(known, key=lambda x: (min((q-x) % period,
                                                  (x-q) % period), x))
            residues[q] = residues[near]
    def key(r, c):
        return r + c if kind == "sum" else c - r
    return [[residues[key(r, c) % period] for c in range(w)]
            for r in range(h)]


