    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Uniform horizontal bands encode a cyclic sequence of row colors.
    bands = {r: row[0] for r, row in enumerate(grid)
             if row and row[0] != 0 and all(v == row[0] for v in row)}
    if bands:
        for period in range(1, h + 1):
            values = {}
            valid = True
            for r, color in bands.items():
                k = r % period
                if k in values and values[k] != color:
                    valid = False
                    break
                values[k] = color
            if valid and len(values) == period:
                return [[values[r % period]] * w for r in range(h)]

    # Otherwise, colored diagonal rays specify a cyclic color sequence by r+c.
    for period in range(1, h + w):
        values = {}
        valid = True
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == 0:
                    continue
                k = (r + c) % period
                if k in values and values[k] != color:
                    valid = False
                    break
                values[k] = color
            if not valid:
