def transform(grid):
    """Recolor rectangular background cavities enclosed by the frame with 4."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]

    # A cavity is a 4-connected background component. Paint it only when its
    # cells exactly fill its bounding rectangle; irregular open regions remain.
    for sr in range(h):
        for sc in range(w):
            if grid[sr][sc] != background or seen[sr][sc]:
                continue
            seen[sr][sc] = True
            q = deque([(sr, sc)])
            cells = []
            min_r = max_r = sr
            min_c = max_c = sc
            while q:
                r, c = q.popleft()
                cells.append((r, c))
                min_r, max_r = min(min_r, r), max(max_r, r)
