from collections import deque


def transform(grid):
    """Fill rectangular background cavities enclosed by the frame with 4."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    frame = next(value for value in counts if value != background)
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]

    for sr in range(h):
        for sc in range(w):
            if grid[sr][sc] != background or seen[sr][sc]:
                continue
            seen[sr][sc] = True
            q = deque([(sr, sc)])
            cells = []
            min_r = max_r = sr
            min_c = max_c = sc
            while q:
                r, c = q.popleft()
                cells.append((r, c))
                min_r, max_r = min(min_r, r), max(max_r, r)
                min_c, max_c = min(min_c, c), max(max_c, c)
                for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                    if (0 <= nr < h and 0 <= nc < w and not seen[nr][nc]
                            and grid[nr][nc] == background):
                        seen[nr][nc] = True
                        q.append((nr, nc))

            # Only a solid rectangular pocket is filled. It must be separated
            # from the exterior by frame cells; the grid bottom can close it.
            height = max_r - min_r + 1
            width = max_c - min_c + 1
            if min_r == 0 or min_c == 0 or max_c == w - 1:
                continue
            if len(cells) != height * width:
                continue
            if not all(grid[min_r - 1][c] == frame for c in range(min_c - 1, max_c + 2)):
