    if not grid:
        return out

    # Locate non-background row blocks, then compare the first and last motif copies.
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    active = [r for r, row in enumerate(grid) if any(v != background for v in row)]
    blocks = []
    for r in active:
        if not blocks or r > blocks[-1][-1] + 1:
            blocks.append([r])
        else:
            blocks[-1].append(r)

    if len(blocks) >= 2 and len(blocks[0]) == len(blocks[-1]):
        for first, last in zip(blocks[0], blocks[-1]):
            first_count = sum(v != background for v in grid[first])
            last_count = sum(v != background for v in grid[last])
            # The less-complete copy receives the marker color where the other copy has a motif cell.
            if first_count >= last_count:
                target, source = last, first
            else:
                target, source = first, last
            for c in range(len(grid[target])):
                if grid[target][c] == background and grid[source][c] != background:
                    out[target][c] = 1
        return out

    # In stripe examples, a contrasting terminal run is the incomplete part.
    for r, row in enumerate(grid):
        if row and row[-1] != row[0]:
            tail = row[-1]
            k = len(row) - 1
            while k > 0 and row[k - 1] == tail:
                k -= 1
            if all(v == row[0] for v in row[:k]):
                out[r][k:] = [1] * (len(row) - k)
    return out

