                comp.add((x, y))
                for dx, dy in forpop:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 1 and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        q.append((nx, ny))
            encloses = any(
                0 <= x + dx < h and 0 <= y + dy < w
                and grid[x + dx][y + dy] == 0
                and (x + dx, y + dy) not in exterior
                for x, y in comp for dx, dy in forpop
            )
            if encloses:
