def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {v: sum(row.count(v) for row in grid) for v in {x for row in grid for x in row if x != 0}}
    noise = max(counts, key=counts.get)
    template_color = min((v for v in counts if v != noise), key=counts.get)
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == template_color]
    r0, c0 = min(r for r, c in points), min(c for r, c in points)
    shape = [(r-r0, c-c0) for r, c in points]
    sh, sw = max(r for r, _ in shape)+1, max(c for _, c in shape)+1
    additions = set()
    for r in range(h-sh+1):
        for c in range(w-sw+1):
            cells = [(r+dr, c+dc) for dr, dc in shape]
            if all(grid[x][y] == 0 for x, y in cells):
                additions.update(cells)
    out = [row[:] for row in grid]
    for r, c in additions:
        out[r][c] = template_color
    return out

