def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row}
    bg = max(colors, key=lambda c: sum(row.count(c) for row in grid))
    out = [row[:] for row in grid]

    def vertical_runs(col):
        runs = []
        r = 0
        while r < h:
            color = grid[r][col]
            if color == bg:
                r += 1
                continue
            end = r
            while end + 1 < h and grid[end + 1][col] == color:
                end += 1
            runs.append((r, end, color))
            r = end + 1
        return runs

    left_runs, right_runs = vertical_runs(0), vertical_runs(w - 1)
    pairs = [(left, right) for left in left_runs for right in right_runs
             if left[2] == right[2] and left[1] - left[0] == right[1] - right[0]]
    if not pairs:
        return out

    left, right = max(pairs, key=lambda pair: pair[0][1] - pair[0][0])
    la, lb, bar_color = left
    ra, rb, _ = right

    def markers(a, b):
        return [(r, c, grid[r][c])
                for r in range(a, b + 1)
                for c in range(1, w - 1)
                if grid[r][c] != bg and grid[r][c] != bar_color]

    lm, rm = markers(la, lb), markers(ra, rb)
    if not lm and not rm:
        return out
    source_left = len(lm) >= len(rm)
    source_a, source_b = (la, lb) if source_left else (ra, rb)
    target_a = ra if source_left else la
    toward = -1 if source_left else 1

    for r in range(source_a, source_b + 1):
        row_marks = [(c, grid[r][c]) for c in range(1, w - 1)
                     if grid[r][c] != bg and grid[r][c] != bar_color]
        if not row_marks:
            continue
        for c, color in row_marks:
            out[r][c] = 4
            x = c + toward
            while 1 <= x < w - 1 and grid[r][x] == bg:
                out[r][x] = color
                x += toward
        # The corresponding row in the opposite panel is painted solid.
        target_r = target_a + (r - source_a)
        if 0 <= target_r < h:
            color = row_marks[0][1]
            for c in range(1, w - 1):
                if grid[target_r][c] == bg:
                    out[target_r][c] = color
    return out

