def transform(grid):
    """Intersect the two panels separated by a uniform nonzero line; mark overlap 2."""
    h, w = len(grid), len(grid[0])
    if any(len(row) != w for row in grid):
        raise ValueError("grid must be rectangular")

    # A solid separator divides two equally sized panels. Either orientation occurs.
    for r, row in enumerate(grid):
        if row and len(set(row)) == 1 and row[0] != 0 and r * 2 == h - 1:
            a, b = grid[:r], grid[r + 1:]
            if len(a) == len(b) and a:
                return [[2 if x != 0 and y != 0 else 0 for x, y in zip(arow, brow)]
                        for arow, brow in zip(a, b)]
