                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            top, left = min(y for y, x in cells), min(x for y, x in cells)
            rel = [(y - top, x - left) for y, x in cells]
            bh, bw = max(y for y, x in rel) + 1, max(x for y, x in rel) + 1
            objects.append((top, left, color, rel, bh, bw))

    objects.sort(key=lambda obj: obj[1])
    out = [[0] * w for _ in range(h)]
    top = left = 0
    for i, (_, _, color, cells, bh, bw) in enumerate(objects):
        if i:
            prev = objects[i - 1]
            top += prev[4] - 1
            left += prev[5] - 1
        for dy, dx in cells:
            y, x = top + dy, left + dx
            if 0 <= y < h and 0 <= x < w:
                out[y][x] = color
    return out


