    """Overlay the two panels separated by a solid 4-row, painting occupied cells 3."""
    separator = next(i for i, row in enumerate(grid) if row and all(value == 4 for value in row))
    top = grid[:separator]
    bottom = grid[separator + 1:]
    return [
        [3 if top[r][c] != 0 or bottom[r][c] != 0 else 0 for c in range(len(top[r]))]
        for r in range(len(top))
    ]

